import type {
  CandidateView,
  ControllerState,
  FaultFlags,
  LogLevel,
  NodeId,
  NodeStatus,
  Outcome,
  RiskPath,
  ProbeSample,
  SimilarityBand,
  TrafficWindow,
} from "./types";
import replaysJson from "../data/replays.json";

// ---------------------------------------------------------------------------
// Local mode replays REAL recorded detector and memory output.
//
// `src/data/replays.json` is generated by `backend/export_replays.py`, which
// runs the trained RandomForest over CICIoMT2024 capture windows and the real
// Memory Agent over the case store. Window probabilities, detection confidence,
// feature attribution, similarity scores and reuse verdicts on this path are
// therefore model output, not constants someone typed.
//
// What IS synthesised here: the agent narratives (investigation prose,
// explanation text) and the outcome telemetry, which come from the LLM and the
// testbed in Live mode. The UI labels this path "local replay" so the
// distinction stays visible.
// ---------------------------------------------------------------------------

interface ReplayCandidate {
  case_id: string; similarity: number; prior_outcome: string; reliability: number;
  reuse_count: number; device_type: string; device_criticality: string;
  executed_response: string; gate: string; reason: string;
}
interface ReplayScenario {
  key: string; name: string; blurb: string;
  device: { id: string; name: string; type: string; criticality: string; ip: string; clinical_role: string };
  src_ip: string;
  replay: { windows: number; rows_per_window: number; attack_start: number; attack_ratio: number; window_seconds: number };
  window_series: TrafficWindow[];
  trigger_index: number;
  confidence: number;
  detector_artifact: Record<string, unknown>;
  incident: Record<string, unknown>;
  source_cardinality: string;
  compared_fields: string[];
  probe_series: ProbeSample[];
  specialists: Record<string, {
    name: string;
    status: "ok" | "unavailable" | "skipped";
    findings: Record<string, unknown>;
    summary: string;
    latency_ms: number;
  }>;
  memory: { band: SimilarityBand; best_case_id: string | null; candidates: ReplayCandidate[] };
}
interface ReplayFile {
  generated_note: string;
  model: Record<string, unknown>;
  scenarios: Record<string, ReplayScenario>;
}

export const REPLAYS = replaysJson as unknown as ReplayFile;
export const MODEL_CARD = REPLAYS.model;

export const THRESHOLDS = {
  HIGH_SIMILARITY: 0.92,
  PARTIAL_SIMILARITY: 0.75,
  MIN_RELIABILITY: 0.8,
  MIN_DETECTOR_CONFIDENCE_FOR_FAST_PATH: 0.95,
  DETECT: 0.5,
};

export interface ScenarioMeta {
  key: string;
  name: string;
  blurb: string;
  device: ReplayScenario["device"];
  confidence: number;
  attackRatio: number;
}

export const SCENARIOS: ScenarioMeta[] = ["low", "medium", "high"]
  .map((k) => REPLAYS.scenarios[k])
  .filter(Boolean)
  .map((s) => ({
    key: s.key,
    name: s.name,
    blurb: s.blurb,
    device: s.device,
    confidence: s.confidence,
    attackRatio: s.replay.attack_ratio,
  }));

export const scenarioByKey = (k: string) => SCENARIOS.find((s) => s.key === k) ?? SCENARIOS[1];
const replayFor = (k: string): ReplayScenario => REPLAYS.scenarios[k] ?? REPLAYS.scenarios.medium;

const toCandidate = (c: ReplayCandidate): CandidateView => ({
  case_id: c.case_id,
  similarity: c.similarity,
  outcome: c.prior_outcome as Outcome,
  reliability: c.reliability,
  reuse_count: c.reuse_count,
  device_type: c.device_type,
  device_criticality: c.device_criticality,
  executed_response: c.executed_response,
  allow: c.gate === "ALLOW",
  reason: c.reason,
});

// ---------------------------------------------------------------------------

export interface StepLog { level: LogLevel; agent: string; msg: string }

export interface GroupMember {
  node: NodeId;
  label: string;
  ms: number;
  status?: NodeStatus;
  logs?: StepLog[];
  artifact?: { title: string; payload: unknown };
}

export interface Step {
  node: NodeId;
  label: string;
  ms: number;
  state?: ControllerState;
  status?: NodeStatus;
  /** a scored traffic window emitted alongside this step */
  window?: TrafficWindow;
  /** availability probes observed during this step */
  probes?: ProbeSample[];
  edges?: Array<{ from: NodeId; to: NodeId; label?: string; kind?: "data" | "control" | "writeback" }>;
  logs?: StepLog[];
  artifact?: { title: string; payload: unknown };
  decision?: { question: string; choice: string; rationale: string };
  fallback?: { trigger: string; action: string; degraded: boolean };
  metrics?: Array<{ key: string; value: string | number }>;
  group?: GroupMember[];
}

export interface BuiltRun {
  steps: Step[];
  meta: ScenarioMeta;
  path: RiskPath;
  band: SimilarityBand;
  candidates: CandidateView[];
  outcome: Outcome;
  summary: string;
  degraded: string[];
}

export function buildRun(scenarioKey: string, f: FaultFlags): BuiltRun {
  const R = replayFor(scenarioKey);
  const meta = scenarioByKey(scenarioKey);
  const dev = R.device;
  const steps: Step[] = [];
  const degraded: string[] = [];

  // The recorded 2 Hz probe timeline is replayed alongside the steps. It was
  // captured against a real HTTP endpoint (see backend/export_replays.py), so
  // the status codes and recovery lag below are measurements, not a curve.
  const probeSeries = R.probe_series ?? [];
  const probeCursor = { i: 0 };
  const takeProbes = (n: number): ProbeSample[] => {
    const out = probeSeries.slice(probeCursor.i, probeCursor.i + n);
    probeCursor.i += out.length;
    return out;
  };

  const flowsAttack = R.detector_artifact.flows_classified_attack as number;
  const flowsTotal = R.detector_artifact.flows_scored as number;

  const candidates = f.memoryDown ? [] : R.memory.candidates.map(toCandidate);
  const band: SimilarityBand = f.memoryDown ? "NONE" : R.memory.band;
  const best = candidates.find((c) => c.allow);

  // --- routing, driven by the REAL detector confidence ---------------------
  let path: RiskPath;
  let routeRationale: string;
  if (dev.criticality === "Critical" || R.confidence < THRESHOLDS.MIN_DETECTOR_CONFIDENCE_FOR_FAST_PATH) {
    path = "HIGH";
    routeRationale =
      `The detector scored the triggering window at ${R.confidence.toFixed(4)} — ${flowsAttack} of ${flowsTotal} ` +
      `flows classified TCP_Flood. That is ${R.confidence < THRESHOLDS.MIN_DETECTOR_CONFIDENCE_FOR_FAST_PATH ? "below" : "above"} ` +
      `the ${THRESHOLDS.MIN_DETECTOR_CONFIDENCE_FOR_FAST_PATH} fast-path floor, and the target is a ` +
      `${dev.criticality}-criticality ${dev.type} (${dev.clinical_role}). High impact plus uncertainty forces the full chain.`;
  } else if (band === "HIGH" && (dev.criticality === "Low" || dev.criticality === "Medium")) {
    path = "LOW";
    routeRationale =
      `Detector confidence ${R.confidence.toFixed(4)} clears the ${THRESHOLDS.MIN_DETECTOR_CONFIDENCE_FOR_FAST_PATH} ` +
      `fast-path floor (${flowsAttack}/${flowsTotal} flows), clinical impact is low (${dev.clinical_role}), and ` +
      `${best?.case_id} matches at ${best?.similarity.toFixed(3)} with a validated SUCCESS outcome. ` +
      `Deep reasoning would add latency without adding decision value.`;
  } else {
    path = "MEDIUM";
    routeRationale =
      `Confident detection (${R.confidence.toFixed(4)}, ${flowsAttack}/${flowsTotal} flows) on a known family, but the ` +
      `target is a ${dev.criticality}-criticality ${dev.type} (${dev.clinical_role}). Reuse must be verified against ` +
      `current context before it is trusted.`;
  }

  if (f.memoryDown && path === "LOW") {
    path = "MEDIUM";
    degraded.push("Fast path withdrawn: memory unavailable, so prior-case reuse cannot be justified.");
  }
  if (f.llmDown) {
    degraded.push("LLM providers unreachable: Investigator, Explainer and Response fell back to deterministic rules.");
  }

  // --- 1. Gateway + Detector: stream the real scored windows ---------------
  steps.push({
    node: "gateway",
    label: "Reading capture windows",
    ms: 300,
    state: "CAPTURED",
    edges: [{ from: "gateway", to: "detector", label: "feature vectors" }],
    logs: [{
      level: "info", agent: "gateway",
      msg: `Replaying ${R.replay.windows} windows x ${R.replay.rows_per_window} flows (${R.replay.window_seconds}s each) from CICIoMT2024 captures`,
    }],
  });

  R.window_series.forEach((w) => {
    const first = w.is_detection && w.index === R.trigger_index;
    steps.push({
      node: "detector",
      label: first
        ? `Detection at window ${w.index}`
        : w.is_detection ? `Window ${w.index} — attack sustained` : `Window ${w.index} — baseline`,
      ms: 200,
      window: w,
      probes: takeProbes(w.index <= R.trigger_index ? 1 : 0),
      status: "active",
      logs: [{
        level: first ? "alert" : w.is_detection ? "warn" : "info",
        agent: "detector",
        msg: first
          ? `DETECTION at window ${w.index} (t+${w.t_offset_s}s): ${w.predicted_attack_rows}/${w.rows} flows classified TCP_Flood, mean p=${w.p_mean.toFixed(3)}`
          : `Window ${w.index} (t+${w.t_offset_s}s): ${w.predicted_attack_rows}/${w.rows} attack flows, mean p=${w.p_mean.toFixed(3)}`,
      }],
    });
  });

  steps.push({
    node: "detector",
    label: "Incident object emitted",
    ms: 340,
    state: "DETECTED",
    edges: [{ from: "detector", to: "planner", label: "incident object", kind: "control" }],
    artifact: { title: "Detector evidence", payload: R.detector_artifact },
  });

  // --- 2. Planner risk assessment -----------------------------------------
  steps.push({
    node: "planner",
    label: "Risk assessment and route selection",
    ms: 640,
    probes: takeProbes(1),
    state: "RISK_ASSESSED",
    edges: [{ from: "planner", to: "memory", label: "similarity query", kind: "control" }],
    decision: {
      question: "How much reasoning does this incident justify?",
      choice: `${path} path`,
      rationale: routeRationale,
    },
    logs: [
      { level: "route", agent: "planner", msg: `Route selected: ${path}` },
      { level: "info", agent: "planner", msg: "Querying Memory Agent before committing to an investigation depth" },
    ],
    artifact: {
      title: "Risk assessment",
      payload: {
        detector_confidence: R.confidence,
        detector_source: "RandomForestClassifier over CICIoMT2024 (real inference)",
        flows_classified_attack: `${flowsAttack}/${flowsTotal}`,
        device: dev,
        selected_path: path,
        explanation_depth: path === "LOW" ? "none" : path === "MEDIUM" ? "one-line" : "detailed",
      },
    },
  });

  // --- 3. Memory ------------------------------------------------------------
  if (f.memoryDown) {
    steps.push({
      node: "memory",
      label: "Case store search",
      ms: 820,
      status: "failed",
      state: "MEMORY_SEARCHED",
      logs: [{ level: "error", agent: "memory", msg: "Case store unreachable — 3 retries exhausted in 850ms" }],
      artifact: { title: "Retrieved cases + reuse gate", payload: { band: "NONE", candidates: [] } },
      fallback: {
        trigger: "Case store unreachable",
        action: "Memory is treated as empty. No prior case may influence this decision. The Planner re-routes to full investigation and queues the write-back for replay.",
        degraded: true,
      },
    });
    degraded.push("Memory unavailable: run completed with zero reuse (slower, more LLM calls, but no wrong-reuse risk).");
  } else {
    steps.push({
      node: "memory",
      label: "Embedding and top-k retrieval",
      ms: 620,
      probes: takeProbes(1),
      state: "SIMILARITY_CLASSIFIED",
      edges: [{ from: "memory", to: "planner", label: `${band} similarity`, kind: "control" }],
      logs: [
        { level: "info", agent: "memory", msg: `Retrieval returned ${candidates.length} candidate case(s)` },
        ...(best
          ? [{ level: "ok" as LogLevel, agent: "memory", msg: `${best.case_id} cleared the gate — similarity ${best.similarity.toFixed(3)}, reliability ${best.reliability}` }]
          : [{ level: "warn" as LogLevel, agent: "memory", msg: "No case cleared the reuse gate" }]),
        ...candidates
          .filter((c) => !c.allow && c.similarity >= THRESHOLDS.PARTIAL_SIMILARITY)
          .map((c) => ({
            level: "warn" as LogLevel, agent: "memory",
            msg: `${c.case_id} BLOCKED despite similarity ${c.similarity.toFixed(3)} — ${c.reason}`,
          })),
      ],
      artifact: {
        title: "Retrieved cases + reuse gate",
        payload: { band, thresholds: THRESHOLDS, candidates: R.memory.candidates },
      },
    });
  }

  // --- planner crash --------------------------------------------------------
  if (f.plannerCrash) {
    steps.push({
      node: "planner",
      label: "Orchestrator process terminated",
      ms: 1050,
      status: "failed",
      state: "SAFE_HOLD",
      logs: [
        { level: "error", agent: "supervisor", msg: "planner-agent exited unexpectedly (SIGKILL) in state SIMILARITY_CLASSIFIED" },
        { level: "warn", agent: "supervisor", msg: "No action had been executed — nothing to roll back" },
        { level: "info", agent: "supervisor", msg: "Restarting planner-agent (attempt 1/3) and replaying durable state" },
        { level: "ok", agent: "planner", msg: "Resumed from checkpoint SIMILARITY_CLASSIFIED" },
      ],
      fallback: {
        trigger: "Planner (Controller) process died mid-incident",
        action:
          "Every state transition is committed to the incident log before the next agent is invoked, so the Planner is restartable. The supervisor replays the last committed state. After 3 failed restarts the pipeline enters SAFE_HOLD: detection and alerting continue, but no autonomous action executes without a human.",
        degraded: true,
      },
    });
    degraded.push("Planner crashed and was restarted from its durable checkpoint; no action was executed during the outage.");
  }

  // --- 4. Investigation -----------------------------------------------------
  const fullInv = path === "HIGH" || band === "NONE";
  const deltaInv = !fullInv && path === "MEDIUM";
  const skipInv = !fullInv && !deltaInv;

  if (skipInv) {
    steps.push({
      node: "planner",
      label: "Skipping investigation",
      ms: 420,
      state: "VERIFY",
      edges: [{ from: "planner", to: "response", label: "verify + adapt", kind: "control" }],
      decision: {
        question: "Does this incident need the Investigator?",
        choice: "No — verify-and-adapt only",
        rationale: `${best!.case_id} matches at ${best!.similarity.toFixed(3)} on a compatible device class with a validated SUCCESS outcome and reliability ${best!.reliability}. The Planner verifies the unchanged fields, updates the changed ones and hands the reconsidered action straight to Response. No specialist runs, and no LLM call is spent on investigation.`,
      },
      logs: [
        { level: "route", agent: "planner", msg: "Investigator: SKIPPED (high-similarity verify path)" },
        { level: "route", agent: "planner", msg: "Explainer: SKIPPED (LOW risk — machine event note only)" },
      ],
    });
    steps.push({ node: "investigator", label: "Not required", ms: 150, status: "skipped" });
    steps.push({ node: "explainer", label: "Not required", ms: 150, status: "skipped" });
  } else {
    const wanted: NodeId[] = deltaInv
      ? ["sub.traffic", "sub.history"]
      : ["sub.log", "sub.threat", "sub.device", "sub.traffic", "sub.history"];

    steps.push({
      node: "planner",
      label: deltaInv ? "Selecting specialists for the delta" : "Dispatching full specialist set",
      ms: 500,
      state: deltaInv ? "DELTA_INV" : "FULL_INV",
      edges: [{ from: "planner", to: "investigator", label: deltaInv ? "delta investigation" : "full investigation", kind: "control" }],
      decision: {
        question: "Which specialist evidence is actually needed?",
        choice: wanted.map((w) => w.replace("sub.", "")).join(" + "),
        rationale: deltaInv
          ? `${best!.case_id} already establishes the attack signature and the device constraints, so those are reused. Only the changed evidence is re-analysed: source cardinality, and whether this source is a repeat offender. Log Analysis, Threat Intel and Device Context are skipped because they cannot change the decision here.`
          : "No prior case cleared the reuse gate, so nothing can be assumed. All five specialists run concurrently and the Investigator fuses whatever comes back.",
      },
      logs: [{ level: "route", agent: "planner", msg: `Specialists invoked: ${wanted.length}/5 (${wanted.map((w) => w.replace("sub.", "")).join(", ")})` }],
    });

    const timedOut = f.subAgentTimeout;
    const firstWanted = wanted[0];

    // Specialist findings come from the recorded real workers in replays.json:
    // computed capture aggregates, registry metadata, or an explicit
    // "unavailable" where the CICIoMT2024 feature schema has nothing to offer.
    const PROVENANCE_LABEL: Record<string, string> = {
      capture: "computed from the scored capture window",
      registry: "testbed device registry",
      "case-store": "counted from the case store",
      unavailable: "no source available in this PoC",
    };
    const AGENT_LOG_NAME: Record<string, string> = {
      log: "log-analysis", threat: "threat-intel", device: "device-context",
      traffic: "traffic-analysis", history: "history-analysis",
    };
    const LABEL_DONE: Record<string, string> = {
      log: "Connection state read", threat: "No feed configured",
      device: "Device class resolved", traffic: "Flood profiled", history: "Recurrence counted",
    };

    const memberFor = (id: NodeId): GroupMember => {
      const key = id.replace("sub.", "");
      const real = R.specialists[key];

      if (id === firstWanted && timedOut) {
        return {
          node: id, label: `${key} timed out`, ms: 1400, status: "failed",
          logs: [{ level: "error", agent: AGENT_LOG_NAME[key] ?? key, msg: "Worker did not respond within its 1400ms budget — returning status=unavailable" }],
          artifact: { title: "Specialist (failed)", payload: { status: "unavailable", findings: {}, note: "No finding is fabricated on timeout. The Investigator records an evidence gap instead." } },
        };
      }
      if (!real) {
        return { node: id, label: "No result", ms: 400, status: "failed" };
      }

      const unavailable = real.status !== "ok";
      const provenance = String(real.findings.provenance ?? "unavailable");
      return {
        node: id,
        label: unavailable ? "Unavailable" : (LABEL_DONE[key] ?? "Done"),
        ms: 520 + Math.min(400, (real.latency_ms ?? 0) * 4),
        status: unavailable ? "degraded" : "ok",
        logs: [{
          level: unavailable ? "warn" : "info",
          agent: AGENT_LOG_NAME[key] ?? key,
          msg: real.summary,
        }],
        artifact: {
          title: `${real.name} findings · ${PROVENANCE_LABEL[provenance] ?? provenance}`,
          payload: { status: real.status, summary: real.summary, ...real.findings },
        },
      };
    };

    steps.push({
      node: "investigator",
      label: `Running ${wanted.length} specialists concurrently`,
      ms: 0,
      probes: takeProbes(2),
      edges: wanted.map((w) => ({ from: "investigator" as NodeId, to: w, label: "invoke", kind: "control" as const })),
      logs: [{ level: "info", agent: "investigator", msg: `Fan-out: ${wanted.length} specialist workers dispatched in parallel` }],
      group: wanted.map(memberFor),
    });

    if (timedOut) degraded.push(`${firstWanted.replace("sub.", "")} specialist timed out; the Investigator recorded an evidence gap and lowered investigation confidence.`);

    steps.push({
      node: "investigator",
      label: f.llmDown ? "Deterministic evidence fusion" : "Fusing evidence",
      probes: takeProbes(1),
      ms: f.llmDown ? 500 : 950,
      status: f.llmDown ? "degraded" : "ok",
      edges: [{ from: "investigator", to: "explainer", label: "investigation result" }],
      logs: f.llmDown
        ? [
            { level: "error", agent: "investigator", msg: "All LLM providers exhausted — groq and gemini key pools returned no usable response" },
            { level: "warn", agent: "investigator", msg: "Falling back to rule-based fusion; confidence_source=rules" },
          ]
        : [{ level: "info", agent: "investigator", msg: `Investigation complete — ${deltaInv ? "delta" : "full"} mode, ${wanted.length} specialist inputs fused` }],
      ...(f.llmDown
        ? { fallback: { trigger: "LLM unavailable during contextual investigation", action: "Specialist findings are concatenated into the structured investigation object, severity is set by the deterministic rule table, and confidence_source is marked 'rules'. The object schema is identical, so every downstream agent still works — only narrative quality drops.", degraded: true } }
        : {}),
      artifact: {
        title: "Structured investigation result",
        payload: {
          mode: deltaInv ? "delta" : "full",
          confidence_source: f.llmDown ? "rules" : "llm+rules",
          confirmed_family: `${R.incident.attack_family}/${R.incident.attack_subtype}`,
          detector_confidence: R.confidence,
          evidence_gaps: [
            ...(timedOut ? [`${firstWanted.replace("sub.", "")}: unavailable`] : []),
            ...wanted
              .map((w) => w.replace("sub.", ""))
              .filter((k) => R.specialists[k]?.status !== "ok" && !(timedOut && `sub.${k}` === firstWanted))
              .map((k) => `${k}: ${String(R.specialists[k]?.findings?.reason ?? "unavailable")}`),
          ],
          severity: dev.criticality === "Critical" ? "high" : "medium",
          differences_from_prior_case: deltaInv
            ? [`device class: ${best?.device_type} -> ${dev.type}`, `source cardinality -> ${R.source_cardinality}`]
            : ["no compatible prior case"],
          response_constraints: [
            ...(dev.criticality === "Critical" ? ["device_isolate DENIED (life-critical class)"] : []),
            ...(R.source_cardinality === "unknown"
              ? ["source cardinality unknown — single-source blocking disallowed, prefer upstream rate limiting"]
              : R.source_cardinality !== "single"
                ? ["single-source blocking ineffective — prefer upstream rate limiting"]
                : []),
            "duration <= 300s without human approval",
            ...(timedOut ? ["confidence reduced: incomplete evidence"] : []),
          ],
        },
      },
    });

    const depth = path === "MEDIUM" ? "one-line" : "detailed";
    steps.push({
      node: "explainer",
      label: f.llmDown ? "Template explanation" : `Generating ${depth} explanation`,
      ms: f.llmDown ? 300 : depth === "one-line" ? 520 : 900,
      status: f.llmDown ? "degraded" : "ok",
      edges: [{ from: "explainer", to: "response", label: "explanation summary" }],
      logs: [{ level: "info", agent: "explainer", msg: `Explanation depth: ${depth}${f.llmDown ? " (template fallback)" : ""}` }],
      ...(f.llmDown
        ? { fallback: { trigger: "LLM unavailable", action: "A slot-filled template explanation is emitted from the structured investigation object. Explanation is never on the containment critical path, so the run continues either way.", degraded: true } }
        : {}),
      artifact: {
        title: `Explanation (${depth})`,
        payload: {
          generated_by: f.llmDown ? "template" : "llm",
          text:
            depth === "one-line"
              ? `${best?.similarity.toFixed(2)} similar to ${best?.case_id}; the target device class changed to ${dev.type} and source cardinality is ${R.source_cardinality}; the prior containment remains compatible if adapted to per-prefix rate limiting.`
              : `A TCP flood is saturating ${dev.name}, a ${dev.criticality} ${dev.type} (${dev.clinical_role}). The detector classified ${flowsAttack} of ${flowsTotal} flows in the triggering window as TCP_Flood, mean probability ${R.confidence.toFixed(4)} — below the ${THRESHOLDS.MIN_DETECTOR_CONFIDENCE_FOR_FAST_PATH} fast-path floor because legitimate telemetry is still interleaved with the attack. The closest prior case, CASE-2025-118, matched at similarity 1.000 but was rejected: its executed action (VLAN quarantine) suppressed a comparable flood while dropping the clinical vitals topic for 26 seconds, and is recorded HARMFUL. The recommended action is therefore upstream rate limiting, which is reversible and preserves the telemetry topic.`,
          xai_note: "Feature attribution is RandomForest importance x deviation from the benign baseline — not SHAP.",
          top_features: R.detector_artifact.top_features,
        },
      },
    });
  }

  // --- 5. Response ---------------------------------------------------------
  // Source cardinality is unknown for these captures, so per-source blocking
  // cannot be justified on any path - the deterministic table selects upstream
  // rate limiting instead. That is the constraint doing its job, not a bug.
  const recommended = f.policyConflict
    ? "device_isolate(600s)"
    : R.source_cardinality === "single"
      ? "temp_source_block(300s)"
      : "upstream_rate_limit(300s)";

  steps.push({
    node: "response",
    label: f.llmDown ? "Deterministic action selection" : "Recommending bounded action",
    probes: takeProbes(1),
    ms: f.llmDown ? 340 : 660,
    state: "RESPONSE_READY",
    status: f.llmDown ? "degraded" : "ok",
    edges: [{ from: "response", to: "policy", label: "recommendation" }],
    logs: [
      ...(f.llmDown ? [{ level: "warn" as LogLevel, agent: "response", msg: "LLM unavailable — action chosen from the deterministic policy table" }] : []),
      { level: "info", agent: "response", msg: `Recommendation: ${recommended}` },
      ...(f.policyConflict ? [{ level: "warn" as LogLevel, agent: "response", msg: "Recommendation touches a restricted action class — the Policy Gate will decide" }] : []),
    ],
    ...(f.llmDown
      ? { fallback: { trigger: "LLM unavailable during response recommendation", action: "The action is selected from a deterministic table keyed on (device class x source cardinality). Narrower coverage than the model, but every entry is inside the pre-approved safe action set.", degraded: true } }
      : {}),
    artifact: {
      title: "Response recommendation",
      payload: {
        selector: f.llmDown ? "deterministic_table" : "llm_recommendation",
        action: recommended,
        reversible: !f.policyConflict,
        prior_case_action: best?.executed_response ?? null,
        prior_case_outcome: best?.outcome ?? null,
        rationale: f.policyConflict
          ? "Model proposed full quarantine to guarantee suppression."
          : `Source cardinality is ${R.source_cardinality} — the capture feature schema carries no addresses — so per-source blocking cannot be shown to work. Upstream rate limiting is selected instead${best ? `, adapted from ${best.case_id} (prior outcome ${best.outcome})` : ""}${dev.criticality === "Critical" ? "; isolation is denied for this device class" : ""}.`,
      },
    },
  });

  // --- 6. Policy gate ------------------------------------------------------
  const gateVerdict = f.policyConflict ? "DOWNGRADE" : "PASS";
  const executedAction = f.policyConflict ? "upstream_rate_limit(300s)" : recommended;
  steps.push({
    node: "policy",
    label: "Deterministic safety validation",
    ms: 380,
    probes: takeProbes(1),
    state: "POLICY_CHECKED",
    status: f.policyConflict ? "degraded" : "ok",
    edges: [{ from: "policy", to: "actuator", label: gateVerdict }],
    decision: {
      question: "Is the recommended action permitted in this context?",
      choice: gateVerdict,
      rationale: f.policyConflict
        ? `RULE-04 violated: device_isolate is not in the allowed action set for device class ${dev.type}. The recommendation is not rejected outright — it is downgraded to the nearest permitted action that still addresses the attack, and the rejection is logged. The model never gets execution authority.`
        : `All checks pass: source is not allowlisted, detector confidence ${R.confidence.toFixed(3)} clears the 0.80 action floor, the action is permitted for device class ${dev.type}, and duration is within the 300s unattended limit.`,
    },
    logs: f.policyConflict
      ? [
          { level: "error", agent: "policy", msg: "RULE-04 FAIL — device_isolate denied for life-critical device class" },
          { level: "warn", agent: "policy", msg: `Downgraded to ${executedAction}` },
        ]
      : [{ level: "ok", agent: "policy", msg: "All policy checks PASS — execution authorised" }],
    ...(f.policyConflict
      ? { fallback: { trigger: "Recommended action violates a hard safety rule", action: "Downgrade to the nearest permitted action rather than reject-and-stall. If no permitted action addresses the attack, the gate escalates to a human instead of executing anything.", degraded: true } }
      : {}),
    artifact: {
      title: "Policy check results",
      payload: {
        checks: [
          { rule: "RULE-01 source is not allowlisted", result: "PASS" },
          { rule: "RULE-02 detector confidence >= 0.80", result: R.confidence >= 0.8 ? "PASS" : "FAIL", detail: `confidence=${R.confidence}` },
          { rule: "RULE-03 duration within 300s unattended limit", result: f.policyConflict ? "FAIL (600s requested)" : "PASS" },
          { rule: `RULE-04 action permitted for device class ${dev.type}`, result: f.policyConflict ? "FAIL" : "PASS" },
          { rule: "RULE-05 action is reversible", result: f.policyConflict ? "FAIL" : "PASS" },
        ],
        verdict: gateVerdict,
        executed_action: executedAction,
      },
    },
  });
  if (f.policyConflict) degraded.push("Policy Gate downgraded the recommended action; the model's proposal was logged as a rejection.");

  // --- 7. Execute + validate ----------------------------------------------
  const outcome: Outcome = f.subAgentTimeout || f.policyConflict ? "PARTIAL" : "SUCCESS";

  // Availability figures come from the recorded probe timeline, split by phase.
  // A whole-run average would mostly measure how long we watched.
  const pct = (xs: ProbeSample[]) =>
    xs.length ? Math.round((100 * xs.filter((p) => p.ok).length) / xs.length) : 0;
  const firstOutage = probeSeries.findIndex((p) => !p.ok);
  const lastOutage = probeSeries.map((p) => p.ok).lastIndexOf(false);
  const noOutage = firstOutage < 0;
  const baselineProbes = noOutage ? probeSeries : probeSeries.slice(0, firstOutage);
  const outageProbes = noOutage ? [] : probeSeries.slice(firstOutage, lastOutage + 1);
  const recoveredProbes = noOutage ? [] : probeSeries.slice(lastOutage + 1);
  const recoveryLag =
    recoveredProbes.length && outageProbes.length
      ? Math.round((recoveredProbes[0].t_offset_s - outageProbes[outageProbes.length - 1].t_offset_s) * 100) / 100
      : null;
  const ttc = recoveryLag ?? 0;
  steps.push({
    node: "actuator",
    label: "Applying action, then waiting on the probe",
    ms: 1600,
    probes: takeProbes(probeSeries.length),
    state: "VALIDATED",
    edges: [{ from: "actuator", to: "memory", label: "validated case write-back", kind: "writeback" }],
    logs: [
      { level: "info", agent: "actuator", msg: `Applied ${executedAction} (rule id fw-8841)` },
      { level: "info", agent: "actuator", msg: "Attack generator still running — measuring suppression and legitimate service" },
      { level: outcome === "SUCCESS" ? "ok" : "warn", agent: "actuator", msg: `Outcome: ${outcome}` },
    ],
    metrics: [
      { key: "Availability · baseline", value: `${pct(baselineProbes)}%` },
      { key: "Availability · under attack", value: `${pct(outageProbes)}%` },
      { key: "Time to recovery", value: recoveryLag !== null ? `${recoveryLag}s` : "not observed" },
      { key: "Probe requests", value: `${probeSeries.length} @ 2/s` },
    ],
    artifact: {
      title: "Availability probe (measured)",
      payload: {
        probe: "GET /gateway/health at 2 requests/sec — 200 = healthy, anything else = outage",
        requests_sent: probeSeries.length,
        responses_200: probeSeries.filter((p) => p.ok).length,
        responses_error: probeSeries.filter((p) => !p.ok).length,
        status_codes_seen: [...new Set(probeSeries.map((p) => p.status_code))],
        baseline_availability_pct: pct(baselineProbes),
        during_attack_availability_pct: pct(outageProbes),
        post_recovery_availability_pct: pct(recoveredProbes),
        time_to_recovery_s: recoveryLag,
        note: "Recorded from a real HTTP probe against the gateway stub. Attack suppression is NOT measured — that needs a gateway traffic counter this PoC has no source for.",
      },
    },
  });

  // --- 8. Write-back --------------------------------------------------------
  if (f.memoryDown) {
    steps.push({
      node: "memory", label: "Write-back queued", ms: 420, status: "degraded", state: "CASE_STORED",
      logs: [{ level: "warn", agent: "memory", msg: "Case store still unreachable — queued to durable outbox for replay" }],
      artifact: { title: "Queued write-back", payload: { queued: true, outbox_depth: 1, note: "The case is not lost. It replays once the store returns, so adaptation resumes where it left off." } },
    });
  } else {
    steps.push({
      node: "memory", label: "Storing validated case", ms: 540, state: "CASE_STORED",
      logs: [
        { level: "ok", agent: "memory", msg: `New case stored with validated outcome ${outcome}` },
        ...(best ? [{ level: "info" as LogLevel, agent: "memory", msg: `${best.case_id}: reuse_count ${best.reuse_count} -> ${best.reuse_count + 1}, reliability ${best.reliability} -> ${(outcome === "SUCCESS" ? Math.min(0.99, best.reliability + 0.02) : Math.max(0, best.reliability - 0.06)).toFixed(2)}` }] : []),
      ],
      artifact: {
        title: "Case written to memory",
        payload: {
          attack_family: `${R.incident.attack_family}/${R.incident.attack_subtype}`,
          device_type: dev.type, device_criticality: dev.criticality,
          source_cardinality: R.source_cardinality,
          specialists_used: skipInv ? [] : deltaInv ? ["traffic", "history"] : ["log", "threat", "device", "traffic", "history"],
          executed_response: executedAction,
          outcome, containment_latency_s: ttc,
          reliability: outcome === "SUCCESS" ? 0.5 : 0.35,
          note: "Reliability starts unproven at 0.5 and only rises as the case is reused and re-validated. One success does not make a case trusted.",
        },
      },
    });
  }

  const summary = skipInv
    ? `Fast path: contained in ${ttc}s using a verified prior case. Investigator and Explainer were never invoked, and no LLM call was spent on investigation.`
    : deltaInv
      ? `Delta path: only the changed evidence was re-investigated (2 of 5 specialists). Contained in ${ttc}s.`
      : `Full path: no prior case cleared the reuse gate, so all 5 specialists ran and a detailed explanation was generated. Contained in ${ttc}s.`;

  return { steps, meta, path, band, candidates, outcome, summary, degraded };
}
